curl -s --max-time 30 -H "X-Scope-OrgID: hackathon" -G "http://10.10.1.139:9009/prometheus/api/v1/query_range" --data-urlencode 'query=sum by (service_name) (increase(traces_span_metrics_calls_total{status_code="STATUS_CODE_ERROR"}[10m]))' --data-urlencode "start=$START" --data-urlencode "end=$END" --data-urlencode "step=600" 2>&1 | python3 -c "
import json,sys,datetime
d=json.load(sys.stdin)
for m in d['data']['result']:
    s=m['metric'].get('service_name','?')
    vals=[(datetime.datetime.utcfromtimestamp(t).strftime('%H:%M'),round(float(v),1)) for t,v in m['values']]
    nz=[x for x in vals if x[1]>0.05]
    if nz: print(s, '->', nz)
"

END=$(date -u +%s)000000000; START=$(( $(date -u +%s) - 1800 ))000000000;
echo "=== Loki: all error-ish lines, last 30m ==="; curl -s --max-time 30 -H "X-Scope-OrgID: hackathon" -G "http://10.10.1.139:3100/loki/api/v1/query_range" --data-urlencode 'query={service_name=~".+"} |~ `(?i)(error|exception|fail|panic|fatal)`' --data-urlencode "start=$START" --data-urlencode "end=$END" --data-urlencode "limit=60" 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
res=d.get('data',{}).get('result',[])
print('streams:',len(res))
for s in res[:20]:
    print('---', s['stream'].get('service_name'), s['stream'].get('severity','') )
    for v in s['values'][:3]: print('   ', v[1][:220])
"

END=$(date -u +%s)000000000; START=$(( $(date -u +%s) - 3600 ))000000000;
curl -s --max-time 30 -H "X-Scope-OrgID: hackathon" -G "http://10.10.1.139:3100/loki/api/v1/query_range" --data-urlencode 'query={service_name="otelcol-contrib"} |= `Error scraping metrics`' --data-urlencode "start=$START" --data-urlencode "end=$END" --data-urlencode "limit=5" 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
for s in d.get('data',{}).get('result',[]):
    for v in s['values'][:2]:
        print(json.dumps(json.loads(v[1]), indent=1)[:1400])
"

curl -s --max-time 30 "http://10.10.1.139:3200/api/traces/5c37f4caf9ad2b7b1c05d252db9c9d34" -H "X-Scope-OrgID: hackathon" 2>&1 > /tmp/tr.json; wc -c /tmp/tr.json; python3 -c "
import json
d=json.load(open('/tmp/tr.json'))
def walk(b):
    for rs in b.get('batches',[]):
        svc=[a['value'].get('stringValue') for a in rs['resource']['attributes'] if a['key']=='service.name']
        svc=svc[0] if svc else '?'
        for ss in rs.get('scopeSpans',[]):
            for sp in ss.get('spans',[]):
                st=sp.get('status',{})
                if st.get('code')==2 or 'ERROR' in str(st.get('code','')):
                    print('ERR SPAN:', svc, '|', sp.get('name'), '|', st)
                    for a in sp.get('attributes',[]):
                        k=a['key']
                        if any(x in k for x in ['error','status','http','rpc','message','exception']):
                            print('    ', k, '=', str(a['value'])[:200])
walk(d)
"

